<?php
use App\Services\AttendanceService as DailyAttendance;
$daily=DailyAttendance::status();$state=$daily['state'];$selfie=$daily['mode']==='selfie'&&$state==='not_checked_in';
?>
<section class="card attendance-card attendance-<?= e($state) ?>" data-daily-attendance data-user-id="<?= $daily['user_id'] ?>" data-revision="<?= e($daily['revision']) ?>" data-endpoint="attendance_checkin.php" data-loading="<?= e(tr('Saving attendance…')) ?>" data-offline="<?= e(tr('Attendance needs an online connection.')) ?>" data-error="<?= e(tr('Unable to update attendance. Please retry.')) ?>" data-stale="<?= e(tr('Your session changed. Reload this page to continue.')) ?>" aria-labelledby="daily-attendance-title">
<div class="attendance-overview"><div class="attendance-heading"><span class="attendance-symbol" aria-hidden="true"><?= icon('check') ?></span><div><h2 id="daily-attendance-title" tabindex="-1"><?= e(tr('Today attendance')) ?></h2><p class="muted attendance-date"><?= e($daily['date_label']) ?> </p></div></div><span class="attendance-status" data-attendance-state="<?= e($state) ?>"><?= e(tr($daily['label'])) ?></span></div>
<div class="attendance-details"><dl class="attendance-times"><div><dt><?= e(tr('Check-in time')) ?></dt><dd><?= e($daily['check_in_time']?date('h:i:s A',strtotime($daily['check_in_time'])):'—') ?></dd></div><div><dt><?= e(tr('Check-out time')) ?></dt><dd><?= e($daily['check_out_time']?date('h:i:s A',strtotime($daily['check_out_time'])):'—') ?></dd></div><div><dt><?= e(tr($state==='completed'?'Total duration':'Elapsed duration')) ?></dt><dd data-attendance-duration><?= e($daily['check_in_time']?$daily['duration']:'—') ?></dd></div></dl>
<?php if(($state==='not_checked_in'&&!$selfie)||$state==='checked_in'): ?>
<form method="post" action="attendance_checkin.php" data-attendance-action><?= csrf_field() ?><input type="hidden" name="action" value="<?= $state==='checked_in'?'check_out':'check_in' ?>"><input type="hidden" name="return_to" value="<?= current_page()==='dashboard.php'?'dashboard.php':'attendance.php' ?>"><button class="btn <?= $state==='checked_in'?'attendance-out-btn':'btn-primary' ?>" aria-label="<?= e(tr($state==='checked_in'?'Mark Attendance Out':'Mark Attendance In')) ?>"><?= icon($state==='checked_in'?'logout':'check') ?><?= e(tr($state==='checked_in'?'Attendance Out':'Attendance In')) ?></button></form>
<?php endif; ?></div>
<?php if($selfie): $cameraToken=DailyAttendance::challenge(); ?>
<p class="muted attendance-note"><?= e(tr('Take a selfie to mark Attendance In here.')) ?></p>
<form method="post" action="attendance_checkin.php" enctype="multipart/form-data" data-attendance-action data-attendance-camera data-error="<?= e(tr('Camera unavailable. Allow camera access and use localhost or HTTPS.')) ?>" data-requesting="<?= e(tr('Requesting camera permission…')) ?>" data-ready="<?= e(tr('Camera ready. Capture your selfie.')) ?>" data-captured="<?= e(tr('Selfie captured. Submit to check in.')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="check_in"><input type="hidden" name="return_to" value="<?= current_page()==='dashboard.php'?'dashboard.php':'attendance.php' ?>"><input type="hidden" name="camera_token" value="<?= e($cameraToken) ?>">
<video class="attendance-preview" autoplay muted playsinline hidden></video><canvas hidden></canvas><img class="attendance-preview" alt="<?= e(tr('Captured selfie')) ?>" hidden>
<p class="muted attendance-note" data-camera-status role="status"><?= e(tr('Camera photo is used as attendance evidence. Face recognition is not applied.')) ?></p><div class="attendance-actions"><button class="btn btn-primary" type="button" data-camera-start aria-label="<?= e(tr('Mark Attendance In')) ?>"><?= icon('check') ?><?= e(tr('Attendance In')) ?></button><button class="btn" type="button" data-camera-capture disabled><?= e(tr('Capture selfie')) ?></button><button class="btn btn-primary" type="submit" disabled><?= e(tr('Submit selfie and check in')) ?></button></div><noscript><?= e(tr('Enable JavaScript to capture your selfie.')) ?></noscript></form>
<?php elseif($state==='recorded'): ?><p class="muted attendance-note"><?= e(tr('Your attendance for today is already recorded. Contact your Teacher or Admin for corrections.')) ?> <span class="pill"><?= e(tr($daily['attendance_status'])) ?></span></p>
<?php endif; ?>
<?php if($daily['attendance_status']&&$state!=='recorded'): ?><span class="pill attendance-record-status <?= e($daily['attendance_status']) ?>"><?= e(tr($daily['attendance_status'])) ?></span><?php endif; ?>
<?php if($daily['selfie_id']): ?><a class="attendance-evidence" href="attendance_selfie.php?id=<?= $daily['selfie_id'] ?>"><?= e(tr('View selfie')) ?></a><?php endif; ?>
<p class="attendance-feedback" data-attendance-feedback role="status" aria-live="polite" aria-atomic="true"></p>
<button type="button" class="btn" data-attendance-refresh hidden><?= e(tr('Refresh attendance status')) ?></button>
</section>
